  return {
    token,
    async listen() { if (server) throw new ValidationError("UI server is already listening"); await app.startCollaborationBridge(); try { server = createServer((request, response) => { void handle(request, response); }); await new Promise<void>((accept, reject) => { server?.once("error", reject); server?.listen(port, host, () => accept()); }); void runDue(); scheduler = setInterval(() => void runDue(), 60_000); scheduler.unref(); const address = server.address(); if (!address || typeof address === "string") throw new Error("UI server did not expose a TCP address"); const displayHost = host === "::1" ? "[::1]" : host; const result = { host, port: address.port, url: `http://${displayHost}:${address.port}` }; if (shouldOpen) openBrowser(result.url); return result; } catch (error) { server = undefined; await app.closeCollaborationBridge(); throw error; } },
    async close() { if (scheduler) { clearInterval(scheduler); scheduler = undefined; } if (server) { const active = server; server = undefined; await new Promise<void>((accept, reject) => active.close((error) => error ? reject(error) : accept())); } await app.closeCollaborationBridge(); },
  };
